// TH14 v1.00b stage4 boss route B (SHOTTYPE not in {0,2,4})
// entry: st04bs2.ecl.txt:468-510 BossBCard2; at-task 512-557; deps default.ecl BossItemCard/Ecl_EtBreak/EffChargePoint2.
// BossB context supplies hitbox/hurtbox 48/48 (r=24), start (0,128), limit and flags.

const TH14_NOTE_YELLOW: int = 1008;   // src etSprite type 40 -> TH14 40; color 0

const TIME_LIMIT: int = 3024;         // task.md: 120 opening + 2900 window + 4 startup
const OPENING_BUFFER: int = 120;

// src etEx index0 type=2 a=1 (ANIM): birth anim omitted by policy, but keep position -= 4*velocity
// (folded into sh_dist). src etEx index1 type=64 a=2 b=13 (BOUNCE U|L|R=13) -> target walls 1|2|4.
xformdef ANIM_BOUNCE {
    bounce_arm(7, 2);
}

// src BossBCard2_at 512-557: rotating fixed-direction ring, count 2/2/3/4, speed 2.0|2.4 +0.0025,
// angle A +0.069813 rad per burst (Easy twice), interval 16/8; native interrupt slot0 at T2400 stops it.
async sub fire_loop() {
    var a: int = 0;                   // src %A, accumulated in BAM (0.069813 rad = 728 BAM)
    var b: fx = 2.4fx;                // src diffF(%B, 2.0, 2.4, 2.4, 2.4), then +0.0025
    var n: int = 2;                   // src etCount difficulty 2/2/3/4
    var interval: int = 8;            // src wait 16 (E) / 8 (NHL)
    var astep: int = 728;             // src 0.069813f, Easy gets it twice
    var bursts: int = 285;            // lit at T121+8k <= 2400 (k=0..284, last T2393)
    var rank: int = global(GVAR_RANK);
    if rank == RANK_EASY {
        b = 2.0fx;
        interval = 16;
        astep = 1456;
        bursts = 143;                 // T121+16k <= 2400 (k=0..142, last T2393)
    }
    if rank == RANK_HARD { n = 3; }
    if rank == RANK_LUNATIC { n = 4; }

    sh_reset(0);                      // src etNew(0) each burst; config is constant here
    sh_sprite(0, TH14_NOTE_YELLOW, 0);
    sh_ring(0, 1);                    // src etAim(0,3): fixed-direction ring
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_xform(0, ANIM_BOUNCE);
    for i in 0..bursts {
        sh_angle(0, a as angle, 0deg);        // src etAngle(0,%A,0.0327249), layers=1
        sh_speed(0, b, 0fx);                  // src etSpeed(0,%B,1.0)
        sh_dist(0, 32fx - 4fx * b);           // src etDist(32) + ANIM position -= 4*velocity
        sh_fire(0);                           // src etOn(0)
        a = a + astep;                        // src %A += 0.069813 (twice on Easy)
        b = b + 0.0025fx;                     // src %B += 0.0025
        wait(interval);                       // src wait([-1])
    }
}

// TH18-verified moveRand recipe (movement.md), params of this card: moveRand(60,0,0.8),
// moveLimit(0,144,280,80) -> box x[-140,140] y[104,184], inner region x±70 y[124,164].
// int slot0 = next source step; fx slot0/1 = logical unit direction.
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx * 0.8fx / 60fx; }   // speed interpolation inherits mode0
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 104fx { ny = 104fx; }
    if ny > 184fx { ny = 184fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_move(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

sub move_dir() {
    // src 412: one signed R/3 or R/4 (+pi branch) sampled per moveRand call; R = pi*U in BAM.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    }
    if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    }
    if $self_x >= -70fx && $self_x <= 70fx {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 124fx {
        if a < 0 { a = -a; }
    }
    if $self_y > 164fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // native +/-pi/2 guard, epsilon 0.05 rad = 522 BAM
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    }
    if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_move(a as angle);
}

sub move_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

async sub boss() {
    set_invuln(65535);
    set_hitbox(24fx);                       // src BossB setHitbox(48,48)
    set_hurtbox(24fx);                      // src BossB setHurtbox(48,48)
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT); // src 491 movePosTime(60,4,0,144); limit handled in helper
    wait(60);
    wait(60);                               // src 493-497 T60 visuals/sound omitted
    spawn fire_loop();                      // src 501 @BossBCard2_at() async at T120
    wait(60);                               // src 504 wait(60) -> T180
    for j in 0..19 {                        // src moveRand at T180+120j, 19 windows to T2400
        move_dir();                         // src 505 moveRand(60,0,0.8)
        move_wait(60);                      // src 506 wait(60) movement duration
        if j < 18 { wait(60); }             // src 508 loop wait(60)
    }
    // T2400 native timeout; BossB3 entry uses etClear(640) on TIMEOUT -> clear surviving tail.
    clear_bullets();
    loop { wait(60); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2300, 0, 0, 0, boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    // src spell(56,2400,...) declaration is presentation/score; its 2400 timeout is in fire_loop.
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
